"""Plain-text absence notices for parents."""

from typing import Iterable, List
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date

def _check_owner(student: Student, marks: List[Mark]) -> None:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for student {mark.student_id!r} given for {student.student_id!r}"
            )

def _compose(student: Student, days: List[date]) -> str:
    name = f"{student.first_name} {student.last_name}"
    count = len(days)
    unit = "day" if count == 1 else "days"
    dates = ", ".join(day.isoformat() for day in days)
    return f"{name} missed {count} {unit} of class.\nDates absent: {dates}"

# ---
def absence_notice(student: Student, marks: Iterable[Mark]) -> str:
    """Short notice naming the student, days missed and the dates in order."""
    marks = list(marks)
    _check_owner(student, marks)
    days = days_missed(marks)
    if not days:
        raise ValueError(f"no absences to report for {student.student_id!r}")
    return _compose(student, days)
